trans = {
    # 0 - 13: Faction rejection & Subjugation Demands
    "AUS_political_events.42.desc": "Permohonan kita untuk bergabung dengan [FROM.GetFactionName] telah ditolak secara dingin. Kita telah berupaya membuktikan kegunaan kita, namun sayangnya [FROM.GetNameDef] telah menetapkan keputusan mereka. Kendati hal ini sangat menjengkelkan, kita tidak boleh patah arang dan sebaliknya harus mencari jalan keluar lain.",
    "AUS_political_events.42.a": "Akan kita buktikan kepada mereka!",
    "AUS_political_events.43.t": "[FROM.GetNameDefCap] Menuntut [Get43PuppetOrNotTitle]",
    "43TitleIsPuppet": "Penyerahan Negara Bawahan Kita",
    "43TitleIsNotPuppet": "Penundukan Kita",
    "AUS_political_events.43.desc": "Tuntutan bernada keras dari [FROM.GetNameDef] tiba di meja kita pagi ini, menuntut agar kita segera [Get43PuppetOrNotDesc]. Ancaman agresi terselubung membayangi tuntutan tersebut, dan sangat mungkin bahwa pertumpahan darah akan pecah seandainya kita menolak usulan mereka ini.",
    "43DescIsPuppet": "menyerahkan kendali atas [FROM.FROM.OWNER.GetNameDef] kepada mereka",
    "43DescIsNotPuppet": "tunduk pada tuntutan mereka dan menjadi negara bawahan di bawah kekuasaan mereka",
    "AUS_political_events.43.a": "Kita tidak berada dalam posisi untuk melawan",
    "AUS_political_events.43.a.tt": "§Y[Get43PuppetOrNotTt]§! mungkin dipaksa untuk bergabung ke dalam Faksi [FROM.GetAdjective]",
    "AUS_political_events.43.b": "Langkahi dulu mayat kami!",
    "AUS_political_events.43.c": "Kita bukan negara bawahan mereka, namun mereka boleh mengambil kembali wilayah-wilayah yang pernah menjadi milik mereka.",
    "43TtIsPuppet": "[FROM.FROM.OWNER.GetNameDefCap]",
    "43TtIsNotPuppet": "[ROOT.GetNameDefCap]",

    # 14 - 32: Subjugation responses & Habsburg on foreign throne
    "AUS_political_events.44.t": "[FROM.GetNameDefCap] Tunduk pada Tuntutan Kita",
    "AUS_political_events.44.desc": "Tanggapan terhadap tuntutan kita kepada [FROM.GetNameDef] sungguh sangat disambut baik. Mereka bersedia menyerahkan [Get44PuppetOrNotDesc] ke bawah kekuasaan kita dan menjadi negara bawahan kita, berlaku seketika. Ini menandai keberhasilan gemilang bagi ikhtiar kita dalam menegakkan kembali imperium kita!",
    "AUS_political_events.44.a": "Wunderbar!",
    "44DescIsPuppet": "[FROM.FROM.OWNER.GetNameDef]",
    "44DescIsNotPuppet": "diri mereka sendiri",
    "AUS_political_events.45.t": "[FROM.GetNameDefCap] Menolak Tuntutan Kita",
    "AUS_political_events.45.desc": "Dalam wujud pembangkangan terang-terangan dan pengabaian atas keselamatan mereka sendiri, [FROM.GetNameDef] telah memutuskan untuk menolak usulan kita. Kesepakatan ini sejatinya saling menguntungkan bagi kedua belah pihak, namun tampaknya mereka tidak memiliki pandangan yang sama mengenai hal ini.",
    "AUS_political_events.45.a": "Kalau begitu kita selesaikan di medan tempur!",
    "AUS_political_events.46.t": "[FROM.GetNameDefCap] Menyerahkan Wilayah Demi Menghindari Penundukan",
    "AUS_political_events.46.desc": "Dalam upaya menghindari penundukan mutlak dan pemotongan kedaulatan mereka, pimpinan [FROM.GetAdjective] mengambil langkah drastis. Alih-alih menjadi negara bawahan kita, mereka menyerahkan wilayah-wilayah mereka yang dulunya pernah kita kuasai kepada kita. Ini bukan hasil yang semula kita perkirakan, dan kita kini harus menentukan sikap apakah akan menerimanya atau menolaknya.",
    "AUS_political_events.46.a": "Bahkan jauh lebih baik!",
    "AUS_political_events.46.b": "Tidak. Kita ingin mereka sepenuhnya berada di bawah kendali kita!",
    "AUS_political_events.47.t": "[FROM.GetNameDefCap] Menolak Usulan Kompromi",
    "AUS_political_events.47.desc": "Terlepas dari upaya terbaik kita untuk menenangkan pihak [FROM.GetAdjective], mereka tampaknya bersikeras bahwa satu-satunya hasil yang dapat diterima adalah kita tunduk pada tuntutan mereka dan membiarkan mereka memasang rezim boneka di negara kita. Mereka menegaskan tidak ada ruang kompromi: kita bersama mereka, atau menjadi musuh mereka.",
    "AUS_political_events.47.a": "Kita tidak akan mau digertak seperti ini!",
    "AUS_political_events.47.b": "Patut dicoba, walau gagal.",
    "AUS_political_events.48.t": "[FROM.GetNameDefCap] Menobatkan Penguasa Habsburg di Singgasana Kita",
    "AUS_political_events.48.desc": "Sudah tak terelakkan mengingat sejarah panjang [FROM.GetNameDef] bahwa, sebagai penguasa atasan kita, cepat atau lambat mereka akan mencampuri urusan politik dalam negeri kita. Kita telah diberitahu secara resmi bahwa mereka telah mengangkat [ROOT.GetLeader] sebagai pemimpin negara kita.",
    "AUS_political_events.48.a": "Tipikal perbuatan wangsa Habsburg...",

    # 33 - 52: Silesia & Castle Habsburg claims
    "AUS_political_events.49.t": "[FROM.GetNameDefCap] Menuntut Penyerahan Silesia",
    "AUS_political_events.49.desc": "Dunia di sekeliling kita tengah bergolak seiring meruncingnya ketegangan. Hari ini kita menerima telegram diplomatik di mana pemerintah [FROM.GetAdjective] menuntut kita menyerahkan Silesia kepada mereka. Silesia secara historis merupakan bagian dari kekaisaran mereka, namun pasca Perang Besar berada di bawah kendali kita hingga saat ini.\\n\\n[FROM.GetNameDefCap] menawarkan kompensasi sejumlah pabrik sebagai imbalan atas penyerahan Niederschlesien dan Oberschlesien dengan harapan dapat mempermudah keputusan kita.",
    "AUS_political_events.49.a": "Baiklah, mereka boleh mengambil wilayah-wilayah itu.",
    "AUS_political_events.49.b": "Kedaulatan wilayah kita bernilai jauh lebih tinggi daripada itu!",
    "AUS_political_events.50.t": "[FROM.GetNameDefCap] Menyerahkan Silesia",
    "AUS_political_events.50.desc": "Kita telah menerima jawaban dari pihak [FROM.GetAdjective] mengenai keinginan kita untuk memperoleh kembali Silesia. Mereka dengan lapang dada menyetujui kesepakatan ini dan akan segera mentransfer wilayah-wilayah tersebut kepada kita. Sebagai imbalannya, kita telah membangun beberapa pabrik di wilayah pilihan mereka.",
    "AUS_political_events.50.a": "Kesepakatan yang paling adil!",
    "AUS_political_events.51.t": "[FROM.GetNameDefCap] Menolak Menyerahkan Silesia",
    "AUS_political_events.51.desc": "Kawat diplomatik dari duta besar [FROM.GetAdjective] bukanlah apa yang kita harapkan. Tidak hanya [FROM.GetNameDef] menolak mentah-mentah kesepakatan ini, mereka melakukannya dengan nada menghina dan meremehkan, mempertanyakan mengapa mereka harus menyetujui hal semacam itu dan atas hak apa kita merasa berhak menuntut wilayah mereka.",
    "AUS_political_events.51.a": "Mereka akan menelan kembali kata-kata angkuh itu!",
    "AUS_political_events.52.t": "[FROM.GetNameDefCap] Menuntut Integrasi Kita",
    "AUS_political_events.52.desc": "Atas dasar klaim kuno dan ikatan darah turun-temurun, penguasa monarki [FROM.GetAdjective] [FROM.GetLeader] menuntut agar kita tunduk ke bawah kekuasaannya. Mengklaim bahwa kota Habsburg, sebagai domain leluhur keluarganya, secara sah merupakan milik negaranya, ia menuntut kita segera berintegrasi, atau menghadapi amukan mesin perang mereka yang baru saja dibangun kembali.",
    "AUS_political_events.52.a": "Kita tidak punya pilihan selain tunduk",
    "AUS_political_events.52.b": "Wangsa Habsburg tidak punya hak apapun atas Habsburg!",
    "AUS_political_events.53.t": "[FROM.GetNameDefCap] Berintegrasi Secara Damai",
    "AUS_political_events.53.desc": "Kita menerima kabar gembira bahwa pihak [FROM.GetAdjective] tidak akan melawan aneksasi negara mereka dan sebaliknya berintegrasi secara damai ke dalam [ROOT.GetName] kita yang agung. Kita akhirnya berhasil merebut kembali kendali dan kepemilikan atas tanah air leluhur kita: puri dan desa Habsburg.",
    "AUS_political_events.53.a": "Akhirnya kembali ke pangkuan kita!",
    "AUS_political_events.54.t": "[FROM.GetNameDefCap] Menolak Klaim Sah Kita atas Habsburg",
    "AUS_political_events.54.desc": "Kita telah menerima tanggapan dari kepemimpinan [FROM.GetAdjective]: mereka tidak akan tunduk pada tuntutan kita. Dengan mencampakkan klaim leluhur kita atas tanah Habsburg, mereka merampas hak milik sah keluarga kerajaan kita dan menodai kehormatan dinasti kita. Penghinaan ini tidak dapat dibiarkan begitu saja!",
    "AUS_political_events.54.a": "Demi kejayaan Habsburg!",

    # 53 - 70: Italian territories (Alto Adige / South Tyrol & Trentino)
    "AUS_political_events.55.t": "[FROM.GetNameDefCap] Ingin Membuat Kesepakatan atas Kepemilikan [39.GetName] dan [850.GetName]",
    "AUS_political_events.55.desc": "Kepemimpinan [FROM.GetAdjective] telah menghubungi kita dengan sebuah proposal. Sejak lama mereka berhasrat untuk memperoleh kembali [39.GetName] dan [850.GetName] dari kita. Mereka datang menawarkan kompensasi pembangunan beberapa pabrik jika kita bersedia menyerahkan wilayah-wilayah ini secara baik-baik.",
    "AUS_political_events.55.a": "Kesepakatan yang adil",
    "AUS_political_events.55.b": "Tanah air kita bukan barang dagangan!",
    "AUS_political_events.56.t": "[GetHostilityItalianClaimTitle56]",
    "AUS_seeks_a_deal_title_56": "[FROM.GetNameDefCap] Menyerahkan Wilayah sebagai Imbalan atas Investasi Industri",
    "AUS_makes_demands_title_56": "[FROM.GetNameDefCap] Menyerahkan Wilayah",
    "AUS_political_events.56.desc": "[GetHostilityItalianClaimDesc56]",
    "AUS_seeks_a_deal_desc_56": "Kesepakatan yang kita ajukan kepada [FROM.GetNameDef] telah disetujui. Sebagai imbalan atas investasi industri dalam jumlah besar, pihak [FROM.GetAdjective] sepakat untuk menyerahkan wilayah [39.GetName] dan [850.GetName] sesuai permohonan kita.",
    "AUS_makes_demands_desc_56": "Tuntutan yang kita layangkan kepada [FROM.GetNameDef] telah disetujui. Pihak [FROM.GetAdjective] akan menyerahkan wilayah [39.GetName] dan [850.GetName] kepada kita segera, dan akhirnya kedua wilayah bersejarah ini kembali menjadi milik kita!",
    "AUS_political_events.56.a": "Kabar yang menggembirakan",
    "AUS_political_events.57.t": "[GetHostilityItalianClaimTitle57]",
    "AUS_seeks_a_deal_title_57": "[FROM.GetNameDefCap] Menolak Kesepakatan yang Kita Usulkan",
    "AUS_makes_demands_title_57": "[FROM.GetNameDefCap] Menolak Tuntutan Kita",
    "AUS_political_events.57.desc": "[GetHostilityItalianClaimDesc57]",
    "AUS_seeks_a_deal_desc_57": "Jawaban dari pihak [FROM.GetAdjective] telah tiba: mereka menolak mentah-mentah kesepakatan tersebut. Menegaskan bahwa tanah air mereka tidak untuk diperjualbelikan, mereka menutup segala pintu perundingan mengenai penjualan wilayah terkait.",
    "AUS_makes_demands_desc_57": "Tuntutan yang kita kirimkan kepada pimpinan [FROM.GetAdjective] ditanggapi dengan kemarahan. Mereka menolak tuntutan kita tanpa menyisakan ruang sedikit pun untuk negosiasi lebih lanjut.",
    "AUS_political_events.57.a": "Mereka akan menyesali keras kepalanya ini!",
    "AUS_political_events.58.t": "Jenderal Alfred Jansa dan Rencana Jansa",
    "AUS_political_events.58.desc": "Kepala Staf Umum kita, Feldmarschall-Leutnant Alfred Jansa, telah merumuskan sebuah doktrin pertahanan komprehensif yang dikenal sebagai 'Rencana Jansa'. Rencana ini mengantisipasi invasi Jerman dengan memanfaatkan benteng alami Pegunungan Alpen dan garis sungai untuk mengulur waktu hingga bantuan internasional tiba.\\n\\nNamun pihak Jerman menganggap rencana ini sebagai provokasi terang-terangan dan menuntut pemberhentian Jansa.",
    "AUS_political_events.58.a": "Pertahankan Jansa dan jalankan rencananya!",
    "AUS_political_events.58.b": "Singkirkan Jansa demi menenangkan Berlin.",
    "AUS_political_events.59.t": "Jansa Mengundurkan Diri",
    "AUS_political_events.59.desc": "Demi meredakan ketegangan diplomatik dengan Jerman, Alfred Jansa telah meletakkan jabatannya sebagai Kepala Staf Umum. Pertahanan Alpen kita kini kehilangan perancang utamanya.",
    "AUS_political_events.59.a": "Pengorbanan yang pahit demi perdamaian.",
    "AUS_political_events.59.b": "Itu adalah keputusan mereka sendiri",
    "AUS_political_events.60.t": "Rencana Jansa Disahkan",
    "AUS_political_events.60.desc": "Pemerintah telah secara resmi mengadopsi Rencana Jansa sebagai doktrin pertahanan nasional utama. Benteng-benteng pertahanan Alpen mulai diperkuat dengan tergesa-gesa.",
    "AUS_political_events.60.a": "Austria akan bertahan!",
    "AUS_political_events.60.a_tt": "§YFranz Böhme§! akan menjadi §GTersedia§! sebagai Kepala Angkatan Darat.\\n\\n§YAlfred Jansa§! akan §RTidak lagi tersedia§! sebagai Kepala Angkatan Darat.",
    "AUS_political_events.60.b": "Justru karena itulah Alfred Jansa harus tetap bertahan!",
    "AUS_political_events.60.b_tt": "§YAlfred Jansa§! akan tetap tersedia sebagai Kepala Angkatan Darat",

    # 71 - 90: German ultimatums against Jansa
    "AUS_political_events.61.t": "[FROM.GetNameDefCap] Memberhentikan Alfred Jansa",
    "AUS_political_events.61.desc": "Pemerintah [FROM.GetAdjective] telah tunduk pada tuntutan kita dan mencopot Alfred Jansa dari posisinya sebagai Kepala Staf. Tanpa keberadaan perwira anti-Jerman ini, pertahanan militer mereka kehilangan taringnya.",
    "AUS_political_events.61.a": "Bagus sekali!",
    "AUS_political_events.62.t": "[FROM.GetNameDefCap] Tetap Mempertahankan Alfred Jansa",
    "AUS_political_events.62.desc": "Meskipun kita menuntut agar [FROM.GetNameDef] membatalkan penerapan apa yang disebut Rencana Jansa dan memastikan perwira tersebut tidak memegang kekuasaan apapun, pihak [FROM.GetAdjective] menolak mendengarkan tuntutan kita. Kita hanya bisa menyimpulkan bahwa ini adalah pertanda buruk bagi hubungan masa depan kita.",
    "AUS_political_events.62.a": "Berani-beraninya mereka?",
    "AUS_political_events.63.t": "Kaum Pengasingan [AUS.GetAdjective] Menawarkan Jasa Mereka",
    "AUS_political_events.63.desc": "Anschluss terhadap [AUS.GetNameDef] telah membuat banyak warga [AUS.GetAdjective] yang menentang pencaplokan ini hidup dalam pengasingan di luar negeri. Sebagian dari pembangkang ini kini tiba di [ROOT.GetNameDef] dan menawarkan jasa mereka di pabrik-pabrik, di jalanan, dan di garis depan.",
    "AUS_political_events.63.a": "Kita tidak dapat menjamin loyalitas mereka",
    "AUS_political_events.63.b": "Kita membutuhkan bantuan mereka",
    "AUS_political_events.64.t": "[FROM.GetNameDefCap] Menawarkan Dukungan Industri",
    "AUS_political_events.64.desc": "Tampaknya tanpa dipicu oleh alasan khusus, pihak [FROM.GetAdjective] menghubungi kita dengan tawaran untuk membantu memajukan industri kita lebih jauh. Mereka menawarkan diri untuk menanggung sebagian dari produksi barang konsumen sipil kita agar kita dapat lebih memfokuskan diri pada pembangunan pabrik.",
    "AUS_political_events.64.a": "Sebuah kejutan yang disambut baik!",
    "AUS_industrial_help": "Dukungan Industri",
    "AUS_political_events.65.t": "[FROM.GetNameDefCap] Menawarkan Dukungan Pasar",
    "AUS_political_events.65.desc": "Tampaknya tanpa dipicu oleh alasan khusus, pihak [FROM.GetAdjective] menghubungi kita dengan tawaran diskon untuk peralatan militer mereka di Pasar Internasional. Apakah ini sekadar taktik agar kita membeli lebih banyak dari mereka atau tawaran tulus, masih belum dapat dipastikan.",
    "AUS_political_events.65.a": "Bagaimanapun juga, ini sangat bermanfaat!",
    "AUS_market_help": "Dukungan Pasar",

    # 91 - 110: Federative Union & Anschluss Avoidance
    "AUS_political_events.66.t": "[FROM.Get.GetNameDefCap] Mengusulkan Uni Federatif",
    "AUS_political_events.66.desc": "[FROM.GetLeader] dari [FROM.GetNameDef] telah menghubungi kita dengan apa yang ia sebut sebagai tawaran persatuan. Seiring federasi berkembang, semakin penting bagi semua negara yang terlibat untuk bekerja sama secara erat tanpa celah. Demi menyederhanakannya, [FROM.GetLeader] menyarankan agar kita semua bersatu di bawah kepemimpinan mereka.\\n\\nKita memang harus memberikan konsesi terkait kedaulatan kita, namun sebagai bagian dari satu negara federatif yang padu, kita juga akan menikmati rasa aman dari tentara yang jauh lebih besar dan kekuatan diplomasi yang lebih disegani.",
    "AUS_political_events.66.a": "Terdengar seperti kesepakatan yang adil",
    "AUS_political_events.66.b": "Ini sama sekali tidak menguntungkan kita!",
    "AUS_political_events.67.t": "[FROM.GetNameDefCap] Menerima Uni Federatif",
    "AUS_political_events.67.desc": "Kabar gemilang bahwa [FROM.GetNameDef] telah sepakat untuk menjadi bagian dari negara federatif baru kita baru saja tiba. Apa yang kita tawarkan terbukti cukup memuaskan bagi mereka untuk menganggap tawaran ini menguntungkan terlepas dari sedikit pengorbanan pada kedaulatan mereka.",
    "AUS_political_events.67.a": "Luar biasa!",
    "AUS_political_events.68.t": "[FROM.GetNameDefCap] Menolak Bergabung dalam Uni Federatif",
    "AUS_political_events.68.desc": "Terlepas dari keuntungan nyata dan fakta bahwa ini adalah yang terbaik bagi federasi, [FROM.GetNameDef] telah menolak usulan kita untuk persatuan yang lebih erat. Kita hanya bisa berspekulasi mengenai motif mereka, namun tampaknya mereka tidak memiliki niat baik bagi keutuhan masa depan federasi.",
    "AUS_political_events.68.a": "Mereka adalah ancaman bagi persatuan federasi!",
    "AUS_political_events.68.b": "Kita akan mengawasi gerak-gerik mereka dengan ketat",
    "AUS_political_events.69.t": "Risiko Anschluss Berhasil Dimitigasi",
    "AUS_political_events.69.desc": "[GetHowAvoidedAnschluss]",
    "AUS_joined_faction": "Dengan kini menjadi bagian dari [ROOT.GetFactionName], tampaknya [GER.GetLeader] telah membatalkan niatnya untuk mencoba mencaplok kita ke dalam [GER.GetNameDef].\\n\\nKita telah berjuang mati-matian memastikan kemerdekaan kita tetap terjaga, dan hasilnya sungguh sepadan dengan segala jerih payah kita.",
    "AUS_became_subject": "[ROOT.GetNameDefCap] tengah mengalami perubahan radikal sejak kita kehilangan kemerdekaan penuh. Kendati banyak di antaranya merupakan dampak pahit dari status bawahan, satu dampak positif yang langka kini tersingkap di hadapan kita. Dengan status kita saat ini, setiap upaya untuk menganeksasi kita akan memicu amarah dari pihak yang jauh lebih besar daripada sekadar bangsa kita sendiri.\\n\\nSadar akan hal itu, tampaknya [GER.GetLeader] telah membatalkan rencana memaksakan pencaplokan kita ke dalam [GER.GetNameDef].",
    "AUS_political_events.69.a": "Secercah harapan di tengah situasi genting kita",
    "AUS_political_events.69.b": "Kedamaian dan keselamatan bagi zaman kita!",
    "AUS_political_events.69.a_tt": "Menghapus Keputusan §YLangkah-Langkah Anti-Anschluss§!.",

    # 111 - 130: Guarantees for factories & St. Germain revisions
    "AUS_political_events.70.t": "Pemerintah [FROM.GetAdjective] Menawarkan Kompensasi sebagai Imbalan Jaminan",
    "AUS_political_events.70.desc": "\\n[FROM.GetLeader] dari [FROM.GetNameDef] telah menghubungi kita secara pribadi kali ini. Interaksi diplomatik kita sebelumnya tidak membuahkan hasil seperti yang mereka harapkan, sehingga mereka memutuskan untuk mengajukan tawaran baru dengan harapan dapat mengubah pendirian kita.\\n\\nMengingat ini adalah masalah hidup dan mati bagi mereka, mereka menawarkan untuk menanggung biaya pembangunan dua pabrik baru di negara kita, dan meyakinkan kita akan rasa terima kasih mereka seandainya kita bersedia mengubah pikiran dan memberi mereka jaminan perlindungan.",
    "AUS_political_events.70.a": "Itu mengubah segalanya!",
    "AUS_political_events.70.b": "Jawaban kita tidak berubah: Tidak.",
    "AUS_political_events.71.t": "[FROM.GetNameDefCap] Memberikan Jaminan atas Bantuan Industri",
    "AUS_political_events.71.desc": "Upaya kita meyakinkan pemimpin [FROM.GetAdjective] [FROM.GetLeader] akhirnya membuahkan hasil manis. Kita diwajibkan menyokong pembangunan dua pabrik untuk mereka, dan kendati ini akan sedikit memperlambat ekspansi industri kita sendiri, kita kini dapat bernapas lebih lega mengetahui bahwa mereka berada di pihak kita seandainya terjadi serangan terhadap kedaulatan kita.",
    "AUS_political_events.71.a": "Kabar baik, akhirnya!",
    "AUS_political_events.72.t": "[FROM.GetNameDefCap] Menolak Membantu Terlepas dari Tawaran Kompensasi",
    "AUS_political_events.72.desc": "Tidak dapat dipungkiri bahwa kita telah berupaya sekuat tenaga. Kita telah merujuk pada Perjanjian Saint-Germain-en-Laye, dan kita telah menawarkan kompensasi jauh melampaui apa yang sewajarnya diharapkan dari negara seukuran kita dalam situasi genting ini. Terlepas dari semua itu, [FROM.GetNameDef] tetap bersikukuh menolak memberi jaminan sesuai perjanjian yang sejatinya mereka rumuskan sendiri. Kita tidak dapat lagi mengandalkan bantuan mereka di masa depan.",
    "AUS_political_events.72.a": "Kita akan bertahan, dan kita buktikan kepada mereka!",
    "AUS_political_events.73.t": "[FROM.GetNameDef] Mengusulkan Revisi Perjanjian Saint-Germain-en-Laye",
    "AUS_political_events.73.desc": "\\nTetap gigih dalam ikhtiar mereka untuk diizinkan mempersenjatai diri kembali, pihak [FROM.GetAdjective] kembali menghubungi kita mengajukan revisi perjanjian yang lebih lunak agar kita dapat mengontrol laju persenjataan mereka. Revisi ini mengizinkan mereka mulai melatih pasukan, namun industri pertahanan mereka akan tetap dibatasi selama satu tahun lagi.",
    "AUS_political_events.73.a": "Kita dapat menerimanya",
    "AUS_political_events.73.a_tt": "Kita akan mendukung usulan revisi [FROM.GetNameDef]. Semua Penjamin harus sepakat agar revisi dapat disahkan.",
    "AUS_political_events.73.b": "Tidak, perjanjian harus tetap utuh.",
    "AUS_political_events.73.b_tt": "Kita §Rtidak§! akan mendukung usulan revisi [FROM.GetNameDef]. Semua Penjamin harus sepakat agar revisi dapat disahkan.",
    "AUS_political_events.73.c": "Jika mereka hendak mempersenjatai diri, kita menuntut adanya pengawas resmi!",
    "AUS_political_events.73.c_tt": "Seorang Pengawas berhaluan demokratis akan ditunjuk untuk bertugas di Austria selama berlakunya Perjanjian yang direvisi",
    "AUS_political_events.74.t": "Para Penjamin Menyetujui Revisi Perjanjian",
    "AUS_political_events.74.desc": "Kabar gembira akhirnya tiba dari para penjamin perjanjian. Setelah negosiasi panjang, mereka sepakat untuk merevisi Perjanjian Saint-Germain-en-Laye dan mengizinkan kita merekrut serta melatih kembali tentara pertahanan kita.",
    "AUS_political_events.74.a": "Langkah awal menuju kedaulatan sejati!",
    "AUS_political_events.75.t": "Para Penjamin Menolak Revisi Perjanjian",
    "AUS_political_events.75.desc": "Para negara penjamin telah menolak mentah-mentah usulan revisi perjanjian kita. Mereka tetap menuntut Austria terikat pada pembatasan yang melumpuhkan kedaulatan kita.",
    "AUS_political_events.75.a": "Kita hanya perlu bertahan lebih lama",
    "AUS_political_events.75.b": "Sudah cukup, kita tidak butuh izin mereka!",

    # 131 - 150: Overseer & Anschluss Inevitable
    "AUS_political_events.76.t": "Para Penjamin Menyetujui Revisi Perjanjian, Menunjuk Pengawas",
    "AUS_political_events.76.desc": "\\nSetelah sekian banyak perdebatan dan diskusi alot, para Penjamin akhirnya mencapai mufakat. Kita akan diizinkan mempersenjatai diri secara bertahap seiring berjalannya waktu; mulai hari ini tidak ada lagi batasan yang menghalangi kita melatih prajurit baru dan menambah jumlah pasukan di medan tempur. Industri pertahanan kita masih dikenai pembatasan meski kini jauh lebih longgar. Pembatasan tersebut akan dicabut sepenuhnya dalam satu tahun, asalkan tidak terjadi perubahan drastis di panggung dunia.\\n\\nNamun kemenangan ini harus dibayar mahal. Para Penjamin tidak mempercayai kemampuan kita untuk menjauhkan diri dari konflik, dan menunjuk seorang pengawas resmi yang wajib berada di pemerintahan kita selama proses transisi ini berlangsung.",
    "AUS_political_events.76.a": "Kita terima persyaratannya!",
    "AUS_political_events.77.t": "Ancaman yang Sudah di Depan Mata",
    "AUS_political_events.77.desc": "Beberapa diplomat kita yang paling berpengalaman dan cakap telah lama memantau ancaman bahwa [GER.GetNameDef] akan melancarkan rencana yang terkadang dikonfirmasi, terkadang disangkal oleh [GER.GetLeader]. Tampaknya telah terjadi pergeseran radikal belakangan ini dan sumber intelijen kita kini meyakini bahwa upaya mencaplok bangsa kita kemungkinan besar sudah berada di depan mata.",
    "AUS_political_events.77.a": "Bersiap menghadapi benturan dahsyat...",
    "AUS_political_events.77.a_tt": "§R[GER.GetNameWithFlag] telah memulai proses Anschluss terhadap kita. Kita tidak dapat lagi mencegahnya secara diplomatis!§!",

    # 151 - 180: Austrian Communists & Austromarxism
    "AUS_political_events.78.t": "Kaum Komunis di [FROM.GetNameDef] Mengharapkan Dukungan Kita",
    "AUS_political_events.78.desc": "Para pemimpin [FROM.GetCommunistParty] di [FROM.GetNameDef] telah menghubungi kita memohon bantuan sekali lagi. Kendati mereka saat ini tidak terlibat dalam konflik bersenjata terbuka, kegagalan pahit perang saudara dan kudeta tahun 1934 bersama kaum Sosial Demokrat masih membekas membara di benak mereka. Mereka mendambakan bantuan kita seiring mereka kembali berikhtiar merebut kekuasaan di negeri mereka.",
    "AUS_political_events.78.a": "Kita akan membantu jika sanggup!",
    "AUS_political_events.78.b": "Kita memiliki prioritas lain yang lebih mendesak",
    "AUS_political_events.79.t": "[FROM.GetNameDefCap] Menawarkan Dukungan Mereka",
    "AUS_political_events.79.desc": "Persis seperti yang kita harapkan, pimpinan [FROM.GetAdjective] telah menawarkan dukungan kepada kita di masa-masa penuh ujian ini. Kita tentu tidak dapat menggantungkan diri sepenuhnya kepada mereka untuk menuntaskan semua masalah kita, namun memiliki dukungan mereka sekali lagi jelas merupakan bantuan yang sangat berharga. Terutama di saat perjuangan perebutan kekuasaan kita terus bergulir.",
    "AUS_political_events.79.a": "Bagus sekali!",
    "AUS_political_events.79.a_tt": "Seandainya perang pecah, [FROM.GetFlag]§Y[FROM.GetNameDef]§! lebih berpeluang mengirimkan sukarelawan dan peralatan sewa-pinjam (lend-lease) kepada kita.",
    "AUS_political_events.80.t": "[FROM.GetNameDefCap] Menolak Panggilan Bantuan Kita",
    "AUS_political_events.80.desc": "Dengan alasan perbedaan ideologis kecil dan keraguan kita terhadap komunisme revolusioner, [FROM.GetNameDef] telah menolak seruan bantuan kita. Kita terpaksa harus berdiri tegak di atas kaki kita sendiri.",
    "AUS_political_events.80.a": "Semula kita sungguh mengira mereka akan membantu!",
    "AUS_political_events.81.t": "[FROM.GetNameDefCap] Menyelaraskan Diri dengan Politik Kita",
    "AUS_political_events.81.desc": "Selama kurun waktu yang panjang, kaum [FROM.GetAdjective] dengan keras kepala memegang teguh bentuk komunisme khas mereka sendiri, yang dikenal sebagai Austromarksisme. Perpecahan politik ini merupakan perpaduan antara demokrasi sosial dan komunisme sejati yang kurang kita sukai. Tampaknya kini mereka akhirnya sadar dan menghapuskan kekeliruan ideologis tersebut untuk menyelaraskan diri dengan kita demi meraih simpati dan perlindungan kita seandainya kekuatan musuh menyerang mereka.",
    "AUS_political_events.81.a": "Bagus, kita akan menawarkan perlindungan kita",
    "AUS_political_events.81.b": "Mereka akan menjadi sekutu yang paling berharga... tapi belum saatnya.",
    "AUS_aligned_with_our_values": "Selaras dengan Nilai-Nilai Kita",
    "AUS_political_events.82.t": "[FROM.GetNameDefCap] Menawarkan Jaminan",
    "AUS_political_events.82.desc": "Keputusan kita untuk menyelaraskan diri lebih erat dengan ideologi politik [FROM.GetLeader] telah disambut baik. [FROM.GetNameDefCap] telah menawarkan jaminan perlindungan kepada kita dan akan menyokong kita seandainya kita menjadi sasaran agresi asing.",
    "AUS_political_events.82.a": "Luar biasa!",
    "AUS_political_events.83.t": "[FROM.GetNameDefCap] Merestui Pergeseran Politik Kita",
    "AUS_political_events.83.desc": "Keputusan kita untuk menyelaraskan diri lebih dekat dengan haluan politik [FROM.GetLeader] telah diterima dengan hangat. [FROM.GetNameDefCap] telah menyatakan apresiasi mereka atas langkah ini sebagai langkah menuju arah yang tepat, dan berharap dapat menyambut kita sebagai sekutu sejati di masa depan.",
    "AUS_political_events.83.a": "Kita menantikan masa itu tiba!",
    "AUS_political_events.84.t": "Kaum [FROM.GetAdjective] Membakar Sentimen Komunis di Negara Kita",
    "AUS_political_events.84.desc": "\\nTelah dilaporkan kepada kita bahwa saat ini ada upaya sistematis dari pihak [AUS.GetNameDef] untuk mengobarkan sentimen komunis di kalangan kaum buruh kita. Kendati hal ini bisa saja sekadar propaganda tanpa bahaya langsung, ada kemungkinan ini adalah persiapan terselubung untuk aksi subversi. Kita belum mengetahui niat sejati mereka, namun kita harus memperhitungkan segala kemungkinan terburuk.",
    "AUS_political_events.84.a": "Kita tidak melihat ada masalah dalam hal ini",
    "AUS_political_events.84.b": "Larang dan bubarkan mereka!",
    "AUS_political_events.84.b_tt": "§RIni dapat memicu konsekuensi yang sangat fatal!§!",
    "AUS_political_events.85.t": "[FROM.GetNameDefCap] Mengizinkan Upaya Pengorganisasian Buruh Kita",
    "AUS_political_events.85.desc": "\\nKita sepenuhnya sadar bahwa kegiatan kita di [FROM.GetNameDef] cepat atau lambat akan terendus. Bersyukur tampaknya [FROM.GetLeader] tidak mempermasalahkan kita menggalang sentimen komunis di kalangan tenaga kerja mereka, memberi pencerahan kepada kaum proletar mengenai hak-hak dan kewajiban mereka sebagai buruh sejati.",
    "AUS_political_events.85.a": "Sempurna",
    "AUS_political_events.85.a_tt": "Membuka keputusan untuk §YMenuntut Pembebasan Kaum Buruh§! setelah fokus §YMenuntut Pembebasan Kaum Buruh§! selesai",
    "AUS_political_events.85.2.a_tt": "Membuka keputusan untuk §YMenuntut Pembebasan Kaum Buruh di [FROM.GetNameDef]§!.",
    "AUS_political_events.86.t": "[FROM.GetNameDefCap] Melarang Gerakan Pengorganisasian Buruh",
    "AUS_political_events.86.desc": "\\nDalam tindakan pelecehan terhadap para pekerjanya sendiri, [FROM.GetLeader] telah melarang segala ikhtiar kita untuk menyadarkan mereka akan hak-hak mereka dalam masyarakat. Ini adalah tindakan permusuhan terbuka, bukan hanya kepada kita, tetapi juga kepada seluruh kaum buruh di seantero dunia.",
    "AUS_political_events.86.a": "Keparat!",
    "AUS_political_events.86.b": "Kita akan membalas permusuhan ini!",
    "AUS_political_events.87.t": "Tuntutan [FROM.GetAdjective] untuk Rezim Komunis",
    "AUS_political_events.87.desc": "Menyusul merebaknya sentimen komunis seiring propaganda [FROM.GetAdjective] menjalar di kalangan kaum buruh kita, sebuah ultimatum kini telah tiba di hadapan kita. [FROM.GetLeader] menuntut agar kita mengizinkan pengambilalihan kekuasaan secara damai oleh kaum komunis sebagaimana ia anggap sebagai kehendak rakyat kita. Seandainya kita menolak, ia menegaskan bahwa mereka akan berdiri membela kaum buruh kita dalam tindakan apa pun yang hendak mereka lancarkan.",
    "AUS_political_events.87.a": "Kita tidak punya pilihan lain.",
    "AUS_political_events.87.b": "Kitalah yang menentukan takdir bangsa kita sendiri.",
    "AUS_political_events.88.t": "[FROM.GetNameDefCap] Membentuk Pemerintahan Komunis",
    "AUS_political_events.88.desc": "Perjuangan tanpa kenal lelah kita di [FROM.GetNameDef] akhirnya terbayar lunas. Kaum buruh bersukacita saat pemimpin baru kawan [FROM.GetLeader] mengambil alih kendali kepemimpinan negara.",
    "AUS_political_events.88.a": "Selamat datang, para kawan seperjuangan!",
    "AUS_political_events.89.t": "[FROM.GetNameDefCap] Menolak Tuntutan Kita",
    "AUS_political_events.89.desc": "Terlepas dari pertanda jelas bahwa rakyat mereka menginginkannya, pihak [FROM.GetAdjective] dan pemimpin mereka [FROM.GetLeader] memilih untuk tidak mengundurkan diri demi pemerintahan yang lebih layak. Kita harus mempertimbangkan pilihan kita dan melakukan apa yang benar demi kaum tertindas.",
    "AUS_political_events.89.a": "Perang terbuka hanya akan membawa kehancuran yang lebih parah",
    "AUS_political_events.89.b": "Suara rakyat tertindas harus didengar!"
}

# Verify and save
with open('scripts/chunks/chunk_1.json', 'r', encoding='utf-8') as f:
    chunk_items = json.load(f)

missing = []
for it in chunk_items:
    k = it['key']
    if k not in trans:
        missing.append(k)

if missing:
    print(f"Warning: {len(missing)} missing keys in chunk 1: {missing[:10]}")
else:
    print(f"Success! All {len(chunk_items)} keys in chunk 1 are translated!")

with open('scripts/chunks/trans_chunk_1.json', 'w', encoding='utf-8') as f:
    json.dump(trans, f, indent=2, ensure_ascii=False)
print("Saved scripts/chunks/trans_chunk_1.json")
